'use strict';
let language;
try { language = localStorage.getItem('tj-language') === 'ko' ? 'ko' : 'en'; } catch { language = 'en'; }
let activeProject = null, activeNode = 0, previousProjectId;
const tr = value => typeof value === 'object' && value !== null && 'en' in value ? value[language] : value;
const esc = text => String(text ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const say = (en,ko) => esc(language === 'en' ? en : ko);
const txt = value => esc(tr(value));
const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
const main = document.getElementById('main');
const resumeUrl = new URL('resume.html', document.currentScript.src).href;
const resumePdfUrl = new URL('assets/Taekjun_Lee_Resume.pdf', document.currentScript.src).href;
function renderChrome(project=null){
 document.documentElement.lang = language;
 document.getElementById('header').innerHTML = `<nav class="nav container" aria-label="${say('Main navigation','주요 메뉴')}"><a class="brand" href="#" aria-label="${say('TJ Lee, home','TJ Lee, 홈')}"><span class="monogram">tj<i>.</i></span><span class="brand-name">TAEKJUN LEE</span></a><div class="nav-links"><a class="desktop-link" href="#work">${say('Selected work','프로젝트')}</a><a class="desktop-link" href="#about">${say('About','소개')}</a><a class="contact-nav" href="#contact">${say('Let’s talk','연락하기')} ${arrow}</a><button class="language" aria-label="${say('Switch to Korean','영어로 전환')}">${language === 'en' ? 'EN / <span class="muted">KO</span>' : '<span class="muted">EN</span> / KO'}</button></div></nav>`;
 document.getElementById('footer').innerHTML = `<div class="container footer-inner"><span>© ${new Date().getFullYear()} Taekjun (TJ) Lee · ${say('Built with purpose.','목적이 분명한 시스템을 만듭니다.')}</span><a href="#">${project?say('Back to overview','전체 소개로'):say('Back to top','처음으로')} ↑</a></div>`;
 document.querySelector('.language').addEventListener('click',()=>{language=language==='en'?'ko':'en';try{localStorage.setItem('tj-language',language);}catch{} const savedScroll=window.scrollY;const savedNode=activeNode;const openNotes=Array.from(document.querySelectorAll('.technical-note')).map(n=>n.open);render();if(activeProject){selectNode(savedNode);document.querySelectorAll('.technical-note').forEach((n,i)=>n.open=!!openNotes[i]);}window.scrollTo({top:savedScroll,behavior:'instant'});document.querySelector('.language').focus({preventScroll:true});});
}
function heroArt(){return `<svg viewBox="0 0 500 470" role="img" aria-label="${say('From field operations through shared data to connected applications','현장 업무에서 공통 데이터를 거쳐 연결된 애플리케이션으로')}"><defs><pattern id="hero-dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#c4cbb9"/></pattern><marker id="ha" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#9ba88c"/></marker></defs><rect x="4" y="25" width="492" height="408" rx="20" fill="url(#hero-dots)"/><g fill="none" stroke="#b6c0a8" stroke-width="1.3" marker-end="url(#ha)"><path d="M140 142H218V193"/><path d="M250 242V285H353V317"/><path d="M282 210H400V165"/><path d="M95 183V350H281"/></g><path d="M250 242V285H353V317" class="flow-edge active"/><g transform="translate(36 85)"><rect width="145" height="99" rx="10" fill="#fff" stroke="#c9d1bf"/><g transform="translate(16 17)" stroke="#67775a" fill="none" stroke-width="1.5"><path d="M0 20V7l13 7V7l13 7V0h8v20H0z"/><path d="M5 16v4m8-4v4m8-4v4"/></g><text x="16" y="62" font-size="13" fill="#283125" font-family="Arial">${say('Field operations','현장 업무')}</text><text x="16" y="81" font-size="9" fill="#7a856f" font-family="monospace">DOMAIN KNOWLEDGE</text></g><g transform="translate(180 192)"><rect width="145" height="98" rx="10" fill="#def68a" stroke="#9db866"/><g transform="translate(16 15)" stroke="#536634" fill="none" stroke-width="1.5"><ellipse cx="13" cy="4" rx="13" ry="4"/><path d="M0 4v18c0 6 26 6 26 0V4M0 12c0 6 26 6 26 0"/></g><text x="16" y="62" font-size="13" fill="#283125" font-family="Arial">${say('Reliable data','신뢰할 수 있는 데이터')}</text><text x="16" y="81" font-size="9" fill="#657845" font-family="monospace">SHARED FOUNDATION</text></g><g transform="translate(335 70)"><rect width="143" height="95" rx="10" fill="#fff" stroke="#c9d1bf"/><g transform="translate(16 16)" stroke="#67775a" fill="none" stroke-width="1.5"><rect width="29" height="22" rx="3"/><path d="M0 6h29M7 12h5m4 0h5M7 17h13"/></g><text x="16" y="60" font-size="13" fill="#283125" font-family="Arial">${say('Connected systems','연결된 시스템')}</text><text x="16" y="79" font-size="9" fill="#7a856f" font-family="monospace">WEB + INTEGRATIONS</text></g><g transform="translate(280 318)"><rect width="185" height="86" rx="10" fill="#283125"/><circle cx="23" cy="24" r="5" fill="#def68a"/><text x="38" y="28" font-size="10" fill="#c8d5b5" font-family="monospace">${say('LESS MANUAL WORK','반복 업무 감소')}</text><text x="18" y="60" font-size="16" fill="#fff" font-family="Arial">${say('Better ways to work.','더 나은 업무 방식.')}</text></g><circle cx="400" cy="210" r="4" fill="#ed6444"/><text x="38" y="244" font-size="9" fill="#7a856f" font-family="monospace">UNDERSTAND.</text><text x="38" y="261" font-size="9" fill="#7a856f" font-family="monospace">CONNECT.</text><text x="38" y="278" font-size="9" fill="#7a856f" font-family="monospace">AUTOMATE.</text></svg>`;}
function miniArt(id){
 const labels=id==='delivery' ? [say('Contractor','업체 제출'),say('Extract','데이터 추출'),say('Validate','자동 검수'),say('Approve','최종 승인')] : id==='master-data' ? [say('Master data','기준정보'),say('Quality','품질'),say('Maintenance','보전'),say('Operations','운영')] : [say('3D models','3D 모델'),say('Asset ID','설비 식별자'),say('Operations','운영 정보'),say('One workspace','통합 업무 공간')];
 const base=`<defs><marker id="mini-${id}" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#8b9b79"/></marker></defs>`;
 const box=(x,y,w,label,sub,accent=false)=>`<g><rect x="${x}" y="${y}" width="${w}" height="55" rx="7" fill="${accent?'#def68a':'#fff'}" stroke="${accent?'#a1b871':'#bfcbb2'}"/><text x="${x+w/2}" y="${y+24}" font-family="Arial,sans-serif" font-size="12" fill="#2d3728" text-anchor="middle">${label}</text><text x="${x+w/2}" y="${y+41}" font-family="monospace" font-size="8" fill="#7a876d" text-anchor="middle">${sub}</text></g>`;
 let graphic='';
 if(id==='delivery')graphic=`<g fill="none" stroke="#9daa8d" stroke-width="1.3" marker-end="url(#mini-${id})"><path d="M143 76H220"/><path d="M277 105V165"/><path d="M220 192H143"/><path d="M85 165V105" stroke-dasharray="4 4"/></g>${box(28,50,115,labels[0],'PORTAL')}${box(220,50,115,labels[1],'APS + LAMBDA')}${box(220,165,115,labels[2],'RULES + RDS')}${box(28,165,115,labels[3],'ENGINEER',true)}<text x="173" y="140" font-family="monospace" font-size="8" fill="#7a876d" text-anchor="middle">EVENT-DRIVEN</text>`;
 else if(id==='master-data')graphic=`<g fill="none" stroke="#9daa8d" stroke-width="1.3" marker-end="url(#mini-${id})"><path d="M144 134H181V43H217"/><path d="M144 134H217"/><path d="M144 134H181V223H217"/></g>${box(26,106,118,labels[0],'VALIDATE + SHARE',true)}${box(217,16,118,labels[1],'QUALITY')}${box(217,106,118,labels[2],'MAINTENANCE')}${box(217,196,118,labels[3],'OPERATIONS')}`;
 else graphic=`<g fill="none" stroke="#9daa8d" stroke-width="1.3" marker-end="url(#mini-${id})"><path d="M145 55H215"/><path d="M145 200H178V145H215"/><path d="M274 83V117"/></g>${box(28,28,117,labels[0],'MODELS')}${box(215,28,117,labels[1],'MAPPING')}${box(28,173,117,labels[2],'QUALITY + HISTORY')}${box(215,117,117,labels[3],'VUE + PYTHON',true)}<g transform="translate(246 200)" stroke="#8c9b78" fill="none"><path d="M0 0l20-11 20 11v24L20 35 0 24zM20 11v24M0 0l20 11L40 0"/></g>`;
 return `<svg viewBox="0 0 365 270" role="img" aria-label="${txt(projects.find(p=>p.id===id).flowTitle)}">${base}${graphic}</svg>`;
}
function card(p,index){return `<a href="#project/${p.id}" class="project-card ${index===0?'featured':''}" aria-label="${say('Read case study: ','사례 보기: ')}${txt(p.short)}"><div class="card-content"><div class="card-meta"><span class="eyebrow">${txt(p.category)}</span><span class="project-number">${p.number} /</span></div><h3>${txt(p.short)}</h3><p class="card-hook">${txt(p.title)}</p><p>${txt(p.summary)}</p><div class="card-proof">${txt(p.cardProof)}</div><div class="card-tags">${p.stack.slice(0,4).map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><div class="card-link"><span>${say('Explore the case study','프로젝트 자세히 보기')}</span>${arrow}</div></div><div class="card-art"><span class="art-tag">${p.id==='master-data'?'SYSTEM ARCHITECTURE':'WORKFLOW OVERVIEW'}</span>${miniArt(p.id)}</div></a>`;}
function confidentiality(compact=false){return compact?`<p class="confidential-note">${say('Company code, internal screens and production data are confidential. Diagrams explain high-level workflows with sensitive details omitted.','회사 코드·내부 화면·운영 데이터는 보안상 공개하지 않습니다. 도식은 민감한 세부 정보를 제외한 상위 업무 흐름을 설명합니다.')}</p>`:`<details class="disclosure" id="disclosure"><summary>${say('About these case studies & confidentiality','사례 공개 범위 · 보안 안내')} <span aria-hidden="true">＋</span></summary><p>${say('My work supports semiconductor manufacturing infrastructure. To respect company confidentiality and industrial-technology protection requirements, I do not publish company source code, internal screenshots, production data or detailed infrastructure configurations. The case studies describe my responsibilities, high-level workflows and engineering decisions with sensitive details omitted. Internal materials are not available as public demos or interview attachments.','반도체 제조 인프라를 지원하는 업무 특성상 회사의 기밀·산업기술 보호 요구사항을 준수하기 위해 소스 코드·내부 화면·운영 데이터·상세 인프라 구성을 공개하지 않습니다. 본 사례는 민감한 세부 정보를 제외하고 담당 범위·상위 업무 흐름·설계 판단을 설명합니다. 회사 내부 자료는 공개 데모나 면접 첨부 자료로 제공하지 않습니다.')}</p></details>`;}
function renderHome(){
 activeProject=null;document.body.classList.remove('project-page');document.title=language==='en'?'TJ Lee — Systems that make work better':'TJ Lee — 업무를 바꾸는 시스템';
 const journey=[L(['Field operations','Understand how engineers actually work.'],['현장 업무','엔지니어의 실제 업무 이해']),L(['Master data','Give every system a shared equipment identity.'],['기준정보','시스템에 공통 설비 기준 공급']),L(['Drawing data','Connect equipment to usable engineering documents.'],['도면 데이터','설비와 활용 가능한 도면 연결']),L(['Shared data','Make governed data available for analysis.'],['데이터 통합','권한 기반의 분석 데이터 공급']),L(['Digital twin','Bring location and operational context together.'],['디지털트윈','공간과 운영 정보의 통합']),L(['Automated intake','Improve data quality from the point of submission.'],['납품 자동화','데이터가 들어오는 단계부터 개선'])];
 main.innerHTML=`<div class="page-enter"><div class="container"><section class="hero" aria-labelledby="hero-title"><div><div class="eyebrow hero-meta"><span class="dot"></span> ${say('SAMSUNG ELECTRONICS · SOFTWARE & SYSTEMS','삼성전자 · 소프트웨어 · 시스템')}</div><h1 id="hero-title">${language==='en'?'I build software<br>that connects<br><em>real-world work.</em>':'현장을 이해하고,<br>데이터를 연결하고,<br><em>업무를 바꿉니다.</em>'}</h1><p class="hero-role">${txt(profile.role)}</p><p class="hero-description">${say('I’m TJ, a facilities engineer turned software developer. I turn complex engineering workflows into connected systems, reliable data and less manual work.','설비 엔지니어에서 시스템 개발자로 성장한 이택준입니다. 복잡한 현장 업무를 분석해 시스템과 데이터를 연결하고, 반복 업무를 줄이는 소프트웨어를 만듭니다.')}</p><p class="hero-stack">Python · FastAPI · Vue.js · SQL · AWS</p><div class="actions"><a class="button" href="#work">${say('Explore my work','프로젝트 살펴보기')} <span aria-hidden="true">↓</span></a><a class="text-link" href="${esc(resumePdfUrl)}" target="_blank" rel="noopener">${say('Résumé (PDF)','이력서 (PDF)')} ${arrow}</a></div></div><div class="hero-art">${heroArt()}<div class="art-caption"><span>01 / ENGINEERING → SOFTWARE</span><span>CONNECTED BY DESIGN</span></div></div></section><div class="hero-foot"><span><strong>${say('7+ years at Samsung Electronics','삼성전자 경력 7년 이상')}</strong> · ${say('Systems development since 2020','2020년부터 시스템 개발 담당')}</span><span>${say('Based in Seoul · Open to relocation to NZ & Australia','서울 기반 · 뉴질랜드·호주 이주 희망')}</span></div><div class="stats" aria-label="${say('Selected project outcomes and scale','주요 프로젝트 성과와 규모')}"><div class="stat"><div class="stat-value">87%<span class="orange"> ↓</span></div><div class="stat-label">${say('Time on equipment registration','설비 등록 업무 소요 시간')}</div><div class="stat-source">MASTER DATA / ${say('MEASURED OUTCOME','측정 성과')}</div></div><div class="stat"><div class="stat-value">17% <span class="orange">→</span> 0%</div><div class="stat-label">${say('Cross-system data discrepancies','시스템 간 데이터 불일치율')}</div><div class="stat-source">MASTER DATA / ${say('MEASURED OUTCOME','측정 성과')}</div></div><div class="stat"><div class="stat-value">8 <span class="orange">↗</span></div><div class="stat-label">${say('Systems in one 3D workspace','하나의 3D 공간에 연결된 시스템')}</div><div class="stat-source">DIGITAL TWIN / ${say('INTEGRATION SCOPE','연계 범위')}</div></div></div><section class="work-section" id="work" aria-labelledby="work-title"><div class="section-heading"><div><div class="eyebrow">01 / ${say('SELECTED WORK','주요 프로젝트')}</div><h2 id="work-title">${say('Complex workflows. Clear outcomes.','복잡한 업무에서, 명확한 변화로.')}</h2></div><p>${say('Three ways I connect business understanding with hands-on software delivery.','업무에 대한 이해를 직접 구현한 소프트웨어로 연결한 세 가지 사례입니다.')}</p></div><div class="selected-grid">${projects.slice(0,3).map(card).join('')}</div>${confidentiality()}<div class="more-work"><div class="more-heading"><span class="eyebrow">${say('MORE OF THE STORY','함께 이어지는 경험')}</span><span class="eyebrow">04 — 07</span></div>${projects.slice(3).map(p=>`<a class="more-row" href="#project/${p.id}"><span class="project-number">${p.number}</span><div><div class="more-title">${txt(p.short)}</div><div class="more-description">${txt(p.category)}</div></div><span class="more-period">${esc(p.period)}</span>${arrow}</a>`).join('')}</div></section></div><section class="journey-section" id="journey"><div class="container"><div class="eyebrow">02 / ${say('ONE CONNECTED JOURNEY','하나로 이어지는 여정')}</div><h2>${say('Each system made the next one possible.','이전의 기반이, 다음의 가능성으로.')}</h2><p class="journey-intro">${say('This work grew from a simple problem: the same equipment meant different things in different systems. A common foundation made better search, shared data and automation possible.','같은 설비가 시스템마다 다르게 관리되는 문제에서 출발했습니다. 공통 기준 위에 검색·데이터 활용·공간 정보·자동화를 차례로 연결했습니다.')}</p><div class="journey-grid">${journey.map((j,i)=>`<div class="journey-step"><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(tr(j)[0])}</h3><p>${esc(tr(j)[1])}</p></div>`).join('')}</div></div></section><div class="container"><section class="about" id="about"><div><div class="eyebrow">03 / ${say('THE PERSON BEHIND THE SYSTEMS','시스템을 만드는 사람')}</div><h2>${say('Engineering context.','현장의 맥락과')}<br>${say('Software ownership.','개발의 책임을 함께.')}</h2><p class="about-copy">${say('I started on the engineering floor, maintaining the infrastructure behind semiconductor manufacturing. That experience still shapes how I build: understand the work, define the data, then deliver the system.','반도체 제조를 지원하는 인프라 설비를 유지보수하며 경력을 시작했습니다. 업무를 이해하고, 데이터를 정의한 뒤, 실제로 사용하는 시스템을 만드는 것이 지금도 개발의 출발점입니다.')}</p><p class="about-copy">${say('At Samsung, my work spans process analysis, data integration, web development and production operations. I work with users and vendors, and stay involved after launch.','삼성전자에서 업무 분석·데이터 연계·웹 개발·운영을 담당하고 있습니다. 사용자·벤더와 함께 문제를 정의하고, 출시 이후의 개선과 운영에도 참여합니다.')}</p><a class="text-link about-link" href="${profile.linkedin}" target="_blank" rel="noopener">${say('Connect on LinkedIn','LinkedIn에서 연결하기')} ${arrow}</a></div><div><div class="career"><div class="career-head"><span>Samsung Electronics</span><span class="eyebrow">2019 — ${say('PRESENT','현재')}</span></div><div class="career-row"><span class="career-date">2020 — ${say('Present','현재')}</span><div><div class="career-name">${say('Systems Engineer','시스템 엔지니어')}</div><p class="career-desc">${say('Business systems, process innovation, full-stack delivery and operational data.','비즈니스 시스템 · 프로세스 혁신 · 풀스택 개발 · 운영 데이터')}</p></div></div><div class="career-row"><span class="career-date">2019 — 2020</span><div><div class="career-name">${say('Facilities Engineer','설비 엔지니어')}</div><p class="career-desc">${say('Infrastructure operations, equipment reliability and maintenance analysis.','인프라 설비 운영 · 신뢰성 · 보전 데이터 분석')}</p></div></div><div class="career-row"><span class="career-date">Sep — Nov 2024</span><div><div class="career-name">${say('U.S. rollout support','미국 사업장 전개 지원')}</div><p class="career-desc">${say('Supported Austin and Taylor FAB rollouts.','Austin·Taylor FAB 전개를 지원했습니다.')}</p></div></div></div><div class="qualifications"><div><span class="eyebrow">${say('EDUCATION','학력')}</span><strong>${say('M.S. Industrial Engineering','산업공학 석사')}</strong><span>${say('Sungkyunkwan University · Feb 2026','성균관대학교 · 2026년 2월')}</span></div><div><span class="eyebrow">${say('ENGLISH','영어')}</span><strong>TOEFL iBT 107 / 120</strong><span>Apr 2025</span></div></div><div class="toolkit-title">${say('BUILD & CONNECT','개발 · 연계')}</div><div class="toolkit">${['Python','FastAPI','Vue.js','SQL','ETL / EAI','REST APIs'].map(s=>`<span>${s}</span>`).join('')}</div><div class="toolkit-title" style="margin-top:22px">${say('DELIVER & OPERATE','배포 · 운영')}</div><div class="toolkit">${['AWS','Linux','Jenkins','Kubernetes','CI/CD','Spotfire'].map(s=>`<span>${s}</span>`).join('')}</div></div></section><section class="contact" id="contact"><div><div class="eyebrow">04 / ${say('WHAT’S NEXT','다음 기회')}</div><h2>${say('Let’s build better business systems.','더 나은 업무 시스템을 함께 만듭니다.')}</h2><p>${say('Looking for software development and business automation opportunities, with New Zealand and Australia as my first relocation choices. Employer visa sponsorship required.','소프트웨어 개발·비즈니스 자동화 기회를 찾고 있습니다. 뉴질랜드·호주 이주를 우선 희망하며, 고용주 비자 지원이 필요합니다.')}</p></div><div class="contact-action"><a class="button" href="mailto:${profile.email}">${profile.email} ${arrow}</a><a class="text-link" href="${esc(resumeUrl)}" target="_blank" rel="noopener">${say('View résumé','이력서 보기')} ${arrow}</a></div></section></div></div>`;
}
function edgePath(from,to,kind){
 const dx=to[1]-from[1],dy=to[2]-from[2];
 if(kind==='loop' && dx===0) return `M${from[1]-80} ${from[2]}H${from[1]-110}V${to[2]}H${to[1]-80}`;
 if(Math.abs(dx)>Math.abs(dy)*.7){const direction=dx>0?1:-1;const sx=from[1]+80*direction,ex=to[1]-80*direction;const mid=(sx+ex)/2;return `M${sx} ${from[2]}H${mid}V${to[2]}H${ex}`;}
 const direction=dy>0?1:-1;const sy=from[2]+44*direction,ey=to[2]-44*direction;const mid=(sy+ey)/2;return `M${from[1]} ${sy}V${mid}H${to[1]}V${ey}`;
}
function workflow(p){
 const paths=p.edges.map(([a,b,kind])=>{const from=p.nodes.find(n=>n[0]===a),to=p.nodes.find(n=>n[0]===b);return `<path class="flow-edge ${kind?'dashed':''}" data-from="${a}" data-to="${b}" d="${edgePath(from,to,kind)}" marker-end="url(#flow-arrow)"/>`;}).join('');
 return `<section class="workflow" aria-labelledby="workflow-title"><div class="workflow-head"><div><div class="eyebrow">${say('SYSTEM WALKTHROUGH','시스템 워크플로')}</div><h2 id="workflow-title">${txt(p.flowTitle)}</h2></div><p class="workflow-hint">${txt(p.flowNote)} ${say('Click a node or use the arrows below.','박스를 누르거나 아래 화살표로 이동하세요.')}</p></div><label class="workflow-select"><span>${say('Explore a stage','단계 선택')}</span><select id="workflow-stage-select">${p.nodes.map((n,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} / ${txt(n[3])}</option>`).join('')}</select></label><div class="diagram-scroll" tabindex="0" role="region" aria-label="${say('Architecture diagram, scroll horizontally on small screens','아키텍처 다이어그램, 작은 화면에서는 가로로 스크롤할 수 있습니다')}"><div class="diagram"><svg class="diagram-lines" viewBox="0 0 1000 430" aria-hidden="true"><defs><marker id="flow-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#8c9d78" stroke-width="1.2"/></marker></defs>${paths}</svg>${p.nodes.map((n,i)=>`<button class="flow-node" style="left:${n[1]/10}%;top:${n[2]/4.3}%" data-node="${i}" aria-pressed="${i===0}" aria-controls="step-detail"><span class="node-num">${String(i+1).padStart(2,'0')} /</span><span class="node-title">${txt(n[3])}</span><span class="node-sub">${txt(n[4])}</span></button>`).join('')}</div></div><div class="workflow-detail" id="step-detail" aria-live="polite" aria-atomic="true"></div></section>`;
}
function selectNode(index,moveView=false){
 const p=activeProject;if(!p)return;activeNode=index;const n=p.nodes[index];const selector=document.getElementById('workflow-stage-select');if(selector)selector.value=String(index);
 document.querySelectorAll('.flow-node').forEach((node,i)=>node.setAttribute('aria-pressed',String(i===index)));
 document.querySelectorAll('.flow-edge[data-from]').forEach(edge=>edge.classList.toggle('active',edge.dataset.from===n[0]||edge.dataset.to===n[0]));
 document.getElementById('step-detail').innerHTML=`<div class="step-badge">${String(index+1).padStart(2,'0')}</div><div class="step-copy"><h3>${txt(n[3])}</h3><p>${txt(n[5])}</p></div><div class="step-controls"><button class="step-control" data-step="-1" aria-label="${say('Previous workflow stage','이전 단계')}" ${index===0?'disabled':''}>←</button><button class="step-control" data-step="1" aria-label="${say('Next workflow stage','다음 단계')}" ${index===p.nodes.length-1?'disabled':''}>→</button></div>`;
 document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>{const direction=Number(button.dataset.step);selectNode(activeNode+direction,true);const next=document.querySelector(`[data-step="${direction}"]:not(:disabled)`);if(next)next.focus({preventScroll:true});else document.querySelector(direction>0?'[data-step="-1"]':'[data-step="1"]').focus({preventScroll:true});}));
 if(moveView){const scroller=document.querySelector('.diagram-scroll');const node=document.querySelector(`[data-node="${index}"]`);scroller.scrollTo({left:node.offsetLeft-scroller.clientWidth/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
}
function projectNav(p){return `<nav class="project-nav" aria-label="${say('Project navigation','프로젝트 이동')}"><div class="container project-nav-inner"><a class="project-nav-back" href="#work">← ${say('All work','전체 사례')}</a><div class="project-nav-links">${projects.map(c=>`<a href="#project/${c.id}" ${c.id===p.id?'aria-current="page"':''}>${txt(c.navLabel)}</a>`).join('')}</div><label class="project-switch"><span class="sr-only">${say('Choose a case study','프로젝트 선택')}</span><select id="project-switch">${projects.map(c=>`<option value="${c.id}" ${c.id===p.id?'selected':''}>${c.number} / ${txt(c.short)}</option>`).join('')}</select></label></div></nav>`;}
function implementationNotes(p){if(!p.details?.length)return '';return `<section class="implementation-notes" id="implementation"><div class="section-heading"><div><div class="eyebrow">${say('TECHNICAL DEPTH','기술 상세')}</div><h2>${say('Inside the implementation.','구현 과정의 판단과 운영.')}</h2></div><p>${say('Expand a topic for constraints, implementation and operational checks. Company-specific identifiers and configurations are omitted.','항목을 펼치면 제약·구현·운영 관점을 확인할 수 있습니다. 회사 고유 식별자와 상세 구성은 제외했습니다.')}</p></div>${p.details.map((d,i)=>`<details class="technical-note"><summary><span class="note-index">0${i+1}</span><span>${txt(d.title)}</span><span class="note-plus" aria-hidden="true">＋</span></summary><div class="note-body"><div><h3>${say('CONSTRAINT','제약')}</h3><p>${txt(d.challenge)}</p></div><div><h3>${say('IMPLEMENTATION','구현')}</h3><p>${txt(d.implementation)}</p></div><div><h3>${say('VERIFICATION & OPERATIONS','검증 · 운영 관점')}</h3><p>${txt(d.verification)}</p></div></div></details>`).join('')}</section>`;}
function metricKind(kind){const names={outcome:L('OUTCOME','성과'),scope:L('SCOPE','적용 규모'),method:L('APPROACH','방법'),capability:L('CAPABILITY','기능'),context:L('BACKGROUND','배경')};return txt(names[kind]||names.scope);}
function renderProject(p){
 activeProject=p;document.body.classList.add('project-page');document.title=`${tr(p.short)} — TJ Lee`;
 const next=projects[(projects.indexOf(p)+1)%projects.length];
 main.innerHTML=`${projectNav(p)}<article class="container page-enter"><div class="case-topbar"><span class="eyebrow">${txt(p.category)} · ${esc(p.period)}</span><span class="status-label"><span class="dot"></span>${txt(p.status)}</span></div><section class="case-hero"><h1>${txt(p.short)}</h1><p class="case-hook">${txt(p.title)}</p><p class="case-summary">${txt(p.summary)}</p><div class="case-role"><span class="eyebrow">${say('MY ROLE','담당 역할')}</span><span>${txt(p.role)}</span></div></section><div class="case-metrics">${p.metrics.map(([value,label],i)=>`<div class="case-metric"><span class="metric-kind">${metricKind(p.metricKinds?.[i])}</span><strong class="${value==='17% → 0%'?'metric-rate':''}">${txt(value)}</strong><span>${txt(label)}</span></div>`).join('')}</div>${p.measurement?`<p class="measure-note">${txt(p.measurement)}</p>`:''}<div class="case-jumps"><a href="#case-change">${say('What changed','업무 변화')} ↓</a><a href="#case-flow">${say('System workflow','시스템 흐름')} ↓</a>${p.details?.length?`<a href="#implementation">${say('Implementation notes','구현 상세')} ↓</a>`:''}</div><div class="change-grid" id="case-change"><div><div class="change-label">${say('BEFORE / THE FRICTION','BEFORE / 기존 문제')}</div><p>${txt(p.before)}</p></div><div><div class="change-label after">${say('AFTER / WHAT CHANGED','AFTER / 달라진 업무')}</div><p>${txt(p.after)}</p></div></div><div id="case-flow">${workflow(p)}</div>${confidentiality(true)}<section class="case-body"><div><div class="eyebrow">${say('THE OUTCOME','변화와 결과')}</div><h2>${say('What became possible.','무엇이 가능해졌는가.')}</h2><p class="case-outcome">${txt(p.outcome)}</p></div><div><div class="eyebrow contribution-title">${say('MY CONTRIBUTION','직접 담당한 부분')}</div><ul class="contributions">${p.contribution.map(c=>`<li>${txt(c)}</li>`).join('')}</ul></div></section>${p.owned?`<aside class="ownership scope-boundary"><h2>${say('Scope boundary · existing platforms & collaborators','담당 범위 구분 · 기반 기술과 협업')}</h2><p>${txt(p.foundation)}</p></aside>`:''}<section class="decision-grid" aria-label="${say('Engineering decisions','설계 판단')}">${p.decisions.map((d,i)=>`<div class="decision"><div class="eyebrow">${say('DESIGN DECISION','설계 판단')} 0${i+1}</div><h3>${txt(d)}</h3><p>${txt(p.decisionText[i])}</p></div>`).join('')}</section>${implementationNotes(p)}<div class="case-stack"><span class="eyebrow">${say('TOOLS & METHODS','기술 · 방법')}</span><div class="toolkit">${p.stack.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div>${p.extension?`<aside class="extension"><span class="eyebrow">${say('EXTENDING THE FOUNDATION','기반 위의 확장')}</span>${txt(p.extension)}</aside>`:''}<div class="case-contact"><span>${say('Discussing a software or automation role?','소프트웨어·자동화 직무를 채용하고 계신가요?')}</span><a class="text-link" href="mailto:${profile.email}">${say('Contact TJ','TJ에게 연락하기')} ${arrow}</a><a class="text-link" href="${esc(resumePdfUrl)}" target="_blank" rel="noopener">${say('Résumé (PDF)','이력서 (PDF)')} ${arrow}</a></div><a class="next-case" href="#project/${next.id}"><div><div class="eyebrow">${say('NEXT CASE STUDY','다음 프로젝트')} / ${next.number}</div><h3>${txt(next.short)}</h3></div>${arrow}</a></article>`;
 document.getElementById('project-switch').addEventListener('change',event=>{location.hash=`project/${event.target.value}`;});
 document.getElementById('workflow-stage-select').addEventListener('change',event=>selectNode(Number(event.target.value),true));
 document.querySelectorAll('[data-node]').forEach(button=>button.addEventListener('click',()=>selectNode(Number(button.dataset.node))));selectNode(0);
}
function render(){
 const hash=location.hash,match=hash.match(/^#project\/([a-z-]+)$/),project=match?projects.find(p=>p.id===match[1]):null;const homeWasVisible=!activeProject,currentScroll=window.scrollY;renderChrome(project);
 if(project){renderProject(project);if(previousProjectId!==project.id)window.scrollTo({top:0,behavior:'instant'});else window.scrollTo({top:currentScroll,behavior:'instant'});previousProjectId=project.id;}
 else {renderHome();previousProjectId=null;if(hash&&document.getElementById(hash.slice(1)))requestAnimationFrame(()=>document.getElementById(hash.slice(1)).scrollIntoView({behavior:'instant'}));else if(!homeWasVisible||hash===''||hash==='#')window.scrollTo({top:0,behavior:'instant'});}
}
window.addEventListener('hashchange',()=>{if(!activeProject&&!location.hash.startsWith('#project/')){const target=document.getElementById(location.hash.slice(1));if(target)target.scrollIntoView();else window.scrollTo({top:0});return;}render();main.focus({preventScroll:true});});
document.addEventListener('click',event=>{const link=event.target.closest('.case-jumps a, .skip');if(!link)return;const target=document.getElementById(link.hash.slice(1));if(target){event.preventDefault();if(target===main)main.focus({preventScroll:true});target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
render();
